import{_ as r,l as o,o as e,c as l,v as i,p as s,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"有限责任下的激励","description":"","frontmatter":{"title":"有限责任下的激励","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/limited-liability-mh.md","filePath":"econ/limited-liability-mh.md","lastUpdated":1789023840000}'),h={name:"econ/limited-liability-mh.md"};function m(c,a,B,A,_,u){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="有限责任下的激励" tabindex="-1">有限责任下的激励 <a class="header-anchor" href="#有限责任下的激励" aria-label="Permalink to &quot;有限责任下的激励&quot;">​</a></h1><div class="epigraph"><p>工资不能为负时，即使代理人风险中性，也不能把随机剩余整段卖给他；激励要靠上侧奖赏，并留下有限责任租金。</p><footer>—— Sappington, Limited Liability Contracts between Principal and Agent, JET, 1983；Innes, Limited Liability and Incentive Contracting, JET, 1990</footer></div><p><a href="/econ/holmstrom-informativeness">上一课</a>把合同自变量收成行动的充足统计。缺口是支付的值域：若 \\(w\\ge 0\\)（或代理人财富有下界），惩罚到不了位。风险中性加可转让剩余本可恢复第一最佳，有限责任把这条路堵死。本课钉下界如何破坏风险分担与一阶方法，不把多任务挤出写成下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>道德风险课说过：风险中性且无财富约束，特许经营——代理人买下整个 \\(x\\)，付固定费——IC 自动满足。有限责任 \\(w(x)\\ge L\\)（常取 \\(0\\)）使固定费收不满：坏结果上代理人赔不出，等于委托人仍担下侧。要诱出努力，必须在好结果上奖得足够陡，于是代理人在好状态拿到租金，IR 不必再绑紧——这是有限责任租金，与筛选里的信息租金不同：这里类型不私有，租金来自「罚不到」。</p><p>一阶方法（用代理人 FOC 代替 IC）在无下界、MLRP、CDFC 时常合法。有下界后，最优合同往往是角点：坏结果付 \\(L\\)，好结果跳到分成或债式。Innes：再加单调性（委托人支付不随 \\(x\\) 升——防篡改产出），最优对风险中性代理人是债：低于面额全归委托人，之上归代理人。代理人成为上侧剩余索取者，激励被集中在似然比高的区域。</p><h3 id="下界改的是可行集-不是偏好" tabindex="-1">下界改的是可行集，不是偏好 <a class="header-anchor" href="#下界改的是可行集-不是偏好" aria-label="Permalink to &quot;下界改的是可行集，不是偏好&quot;">​</a></h3><p>代理人仍可以厌恶风险；即使他风险中性，下界单独就造成效率损失。不要把有限责任租金叫成信息租金：签约时信息对称，IR 可以在期望上松，只因为点态赔不起。</p><p><span class="marginnote">Sappington 强调：有限责任下最优通常实施比第一最佳更低的努力，并给代理人严格正的期望租金。一阶方法失败，是因为真正的 IC 是全局的，角点工资让代理人的目标对 \\(a\\) 不必凹。</span></p><p>债式合同不是因为「债务激励更强」的口号，而是单调性加有限责任把最优推到这条边界。 没有单调性，最优可以是在最高似然比的结果上把奖堆成一团（live-or-die），更极端。 法庭若不允许活-或-死，单调性是制度约束，不是技术。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：隐藏行动、可验证 \\(x\\)、约束 \\(w\\ge L\\)。风险中性教具先算清：第一最佳做不成，最优在 \\(L\\) 与分成之间跳。再加风险厌恶：保险需求与下界同时绑，工资更扁。检查一阶方法：若最优是角点，用 Grossman–Hart 的离散实施更安全。</p>',12)),(e(),s(E,null,{default:t(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FB%5B%22%E9%A3%8E%E9%99%A9%E4%B8%AD%E6%80%A7%E6%97%A0%E7%BA%A6%E6%9D%9F%EF%BC%9A%E5%8D%96%E6%96%AD%E5%89%A9%E4%BD%99%22%5D%20--%3E%20LL%5B%22w%20%E2%89%A5%20L%22%5D%0A%20%20LL%20--%3E%20RENT%5B%22%E7%BD%9A%E4%B8%8D%E5%88%B0%20%E2%86%92%20%E6%9C%89%E9%99%90%E8%B4%A3%E4%BB%BB%E7%A7%9F%E9%87%91%22%5D%0A%20%20LL%20--%3E%20DEBT%5B%22%E5%8D%95%E8%B0%83%E6%80%A7%E4%B8%8B%E5%80%BA%E5%BC%8F%E5%90%88%E5%90%8C%22%5D%0A%20%20FOA%5B%22%E4%B8%80%E9%98%B6%E6%96%B9%E6%B3%95%22%5D%20--%3E%20FAIL%5B%22%E8%A7%92%E7%82%B9%E5%A4%84%E5%8F%AF%E4%BB%A5%E9%9D%9E%E6%B3%95%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>激励需要似然比高的结果相对更甜。没有下界，可以同时压低坏结果、抬高好结果，均值按 IR 抽干。有下界后，坏结果已经贴在 \\(L\\)，只能抬好结果，均值升，代理人得租。委托人面对的价格是：每单位激励更贵（因为伴随租金），于是少买激励，努力低于第一最佳。债把「抬好结果」写成代理人拿走尾部，等价于在上侧把似然比用足。</p><p>充足统计原则仍在：下界不改变「该用哪些信号」，只改变「在这些信号上能罚多深」。相对绩效若把工资推到 \\(L\\) 以下，会被截断，过滤的好处打折。一阶方法把 IC 换成代理人的 FOC，要求目标对 \\(a\\) 充分凹；贴着 \\(w=L\\) 的角点使凹性容易破，表面上满足 FOC 的合同可能实施了另一行动。应用里两行动或 Grossman–Hart 的线性不等式更稳。</p><p>Sappington 的要点是下界单独造成效率损失，即使风险中性。 Innes 再加上单调性，把最优推到债的边界，而不是活-或-死的奖金堆。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有限责任若两边都有（委托人也破产），风险分担更糟，债的优先权故事进入公司金融，本课不写资本结构。代理人若同时有隐藏类型，租金叠两层，需显示原理。连续行动加角点，一阶方法的正则条件更容易破，应用里应回到两行动或 Grossman–Hart。</p><p>后课默认：有限责任 \\(\\Rightarrow\\) 即使风险中性也偏离第一最佳，并留下租金；最优常呈债式或上侧分成。委托–代理规划要把 \\(w\\ge L\\) 写进约束。</p><h3 id="租金来源对照" tabindex="-1">租金来源对照 <a class="header-anchor" href="#租金来源对照" aria-label="Permalink to &quot;租金来源对照&quot;">​</a></h3><p>筛选：类型在签约前私有，IC 逼你给优势类型留租。道德风险无下界：IR 绑紧，无事前租，只有风险补偿。有限责任：事前对称，但点态 \\(w\\ge L\\) 让 IR 变松，租是执行约束的影子价格。三笔账不要加进同一句话。</p><p><span class="marginnote">Innes 1990 的单调性：委托人的所得随产出不降，否则代理人可销毁产出把合同推到更有利的区间。债满足这一约束，活-或-死一般不满足。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工资下界堵死特许经营，风险中性也买不回第一最佳。</li><li>激励改走上升段，代理人拿有限责任租金。</li><li>一阶方法在角点处不可靠；单调性下债式常最优。</li><li>这与筛选信息租金来源不同。</li><li>出处：Sappington, <em>JET</em> 1983；Innes, <em>JET</em> 1990。</li></ul>',12))])}const f=r(h,[["render",m]]);export{L as __pageData,f as default};
